@section('content')<section class="panel"><div class="panel-header"><div><h2>Mandantenspezifische Freigaben</h2><p>„Paket übernehmen“ verwendet die Paketdefinition. Overrides haben Vorrang und werden ausschließlich für diesen Mandanten gespeichert.</p></div></div><form method="post" action="{{ route('taxi-control.superadmin.tenants.features.update',$tenant) }}">@csrf @method('PUT')<div class="table-wrap"><table><thead><tr><th>Feature</th><th>Paket</th><th>Override</th><th>Limit</th></tr></thead><tbody>@foreach($features as $feature)@php($override=$overrides->get($feature->id))<tr><td><strong>{{ $feature->name }}</strong><br><code>{{ $feature->key }}</code></td><td>{{ in_array($feature->id,$packageFeatureIds)?'Aktiv':'Nicht enthalten' }}</td><td><select name="features[{{ $feature->id }}][mode]"><option value="inherit" @selected(!$override)>Paket übernehmen</option><option value="enabled" @selected($override && $override->enabled)>Erzwingen: aktiv</option><option value="disabled" @selected($override && !$override->enabled)>Erzwingen: inaktiv</option></select></td><td><input name="features[{{ $feature->id }}][limit]" value="{{ $override->limit_value ?? '' }}" placeholder="optional"></td></tr>@endforeach</tbody></table></div><div class="form-actions top-gap"><a class="btn" href="{{ route('taxi-control.superadmin.tenants.edit',$tenant) }}">Zum Mandanten</a><button class="btn btn-primary">Overrides speichern</button></div></form></section>@endsection
